host_operator_src="""
#include "argmin_over_a_dimension_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 通过输入/输出元素个数推导最后一维长度
    // 假定自定义算子对输入张量的最后一维执行argmin，输出为去掉最后一维后的形状
    uint64_t inSize = context->GetInputShape(0)->GetOriginShape().GetShapeSize();
    uint64_t outSize = context->GetOutputShape(0)->GetOriginShape().GetShapeSize();
    if (outSize == 0) {
        return ge::GRAPH_FAILED;
    }
    uint32_t hLength = static_cast<uint32_t>(inSize / outSize);
    uint32_t totalOuter = static_cast<uint32_t>(outSize);

    ArgminOverADimensionCustomTilingData tiling;
    context->SetBlockDim(BLOCK_DIM);
    tiling.set_totalOuter(totalOuter);
    tiling.set_hLength(hLength);
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0; // 本算子不需要额外workspace（内部使用UB临时buffer）

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // 简化实现：形状推导由上层Python侧显式创建输出Tensor完成
    // 这里保持与输入一致，具体输出实际形状以调用侧传入的Tensor为准
    const gert::Shape* in_shape = context->GetInputShape(0);
    gert::Shape* out_shape = context->GetOutputShape(0);
    *out_shape = *in_shape;
    return GRAPH_SUCCESS;
}
static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    // 输出为int32类型
    context->SetOutputDataType(0, ge::DT_INT32);
    return ge::GRAPH_SUCCESS;
}
}

namespace ops {
class ArgminOverADimensionCustom : public OpDef {
public:
    explicit ArgminOverADimensionCustom(const char* name) : OpDef(name)
