#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor argmin_over_a_dimension_custom_impl_npu(const at::Tensor& x) {
    // 输出为去掉最后一维后的形状，dtype int32（随后可在Python侧转为long）
    std::vector<int64_t> out_sizes;
    out_sizes.reserve(x.dim() > 0 ? x.dim() - 1 : 0);
    for (int64_t d = 0; d < x.dim() - 1; ++d) {
        out_sizes.push_back(x.size(d));
    }
    at::Tensor result = at::empty(out_sizes, x.options().dtype(at::kInt));
    EXEC_NPU_CMD(aclnnArgminOverADimensionCustom, x, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("argmin_over_a_dimension_custom", &argmin_over_a_dimension_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("argmin_over_a_dimension_custom", &argmin_over_a_dimension_custom_impl_npu, "argmin over last dimension");
}
